def apply(inputs, premises):
    lengths = inputs["bag_lengths"]
    widths = inputs["bag_widths"]
    heights = inputs["bag_heights"]
    weights = inputs["bag_weights"]
    profile = inputs["fee_profile"]
    position_fees = premises["domestic_basic_position_fees"]
    weight_fees = premises["domestic_weight_fees"]
    if profile == "asia_premium":
        position_fees = premises["asia_premium_position_fees"]
        weight_fees = premises["asia_weight_fees"]
    total = inputs["ticket_price"]
    carryon_used = False
    checked_index = 0
    count = min(len(lengths), len(widths), len(heights), len(weights))
    for i in range(count):
        carryon = False
        if not carryon_used:
            carryon = lengths[i] <= premises["carryon_caps"][0] and widths[i] <= premises["carryon_caps"][1] and heights[i] <= premises["carryon_caps"][2]
        if carryon:
            carryon_used = True
        else:
            position = checked_index
            if position >= len(position_fees):
                position = len(position_fees) - 1
            base_fee = position_fees[position]
            overweight = 0
            if weights[i] > 50 and weights[i] <= 53:
                overweight = weight_fees[0]
            elif weights[i] > 53 and weights[i] <= 70:
                overweight = weight_fees[1]
            elif weights[i] > 70 and weights[i] <= 100:
                overweight = weight_fees[2]
            linear_size = lengths[i] + widths[i] + heights[i]
            oversize = 0
            if linear_size > 62 and linear_size <= 65:
                oversize = premises["oversize_fees"][0]
            elif linear_size > 65 and linear_size <= 115:
                oversize = premises["oversize_fees"][1]
            total = total + base_fee + max(overweight, oversize)
            checked_index = checked_index + 1
    return {"answer": int(total)}
